/**
 * 三类专项的逐文件执行器。
 *
 * <p>每个目标独立准备、规划、调用和发布；一个文件失败不丢弃其他文件的结果。
 * 片段与文件共用公共模型并发许可；每次实际调用先由公共入口落盘，格式错误最多再试 2 次。
 * 完整发布要求全部单元成功；部分成功发布 INCOMPLETE 结果，供阅读但不能进入正式选材。
 */
@Service
@ConditionalOnProperty(prefix = "agent.datasource", name = "url")
public class SpecialistTaskWorker implements TaskWorker {

    private static final Logger log = LoggerFactory.getLogger(SpecialistTaskWorker.class);

    private final AgentDatabase db;
    private final ObjectMapper mapper;
    private final MaterialPreparationService preparation;
    private final DeclarationEnhancementService enhancement;
    private final CouplingFactsBuilder couplingFacts;
    private final RepositoryReadService repository;
    private final JavaStructureParser structureParser;
    private final SpecialistSplitPlanner planner;
    private final PromptAssemblyService promptAssembly;
    private final SpecialistPromptBuilder promptBuilder;
    private final SpecialistResultParser resultParser;
    private final SpecialistResultValidator validator;
    private final SpecialistResultPublisher publisher;
    private final ModelInvocationService invocation;
    private final ModelCapacityService capacity;
    private final TaskExecutionGuard guard;
    private final SpecialistExecutionProperties properties;

    public SpecialistTaskWorker(AgentDatabase db, ObjectMapper mapper,
                                MaterialPreparationService preparation,
                                DeclarationEnhancementService enhancement,
                                CouplingFactsBuilder couplingFacts,
                                RepositoryReadService repository,
                                JavaStructureParser structureParser,
                                SpecialistSplitPlanner planner,
                                PromptAssemblyService promptAssembly,
                                SpecialistPromptBuilder promptBuilder,
                                SpecialistResultParser resultParser,
                                SpecialistResultValidator validator,
                                SpecialistResultPublisher publisher,
                                ModelInvocationService invocation,
                                ModelCapacityService capacity,
                                TaskExecutionGuard guard,
                                SpecialistExecutionProperties properties) {
        this.db = db;
        this.mapper = mapper;
        this.preparation = preparation;
        this.enhancement = enhancement;
        this.couplingFacts = couplingFacts;
        this.repository = repository;
        this.structureParser = structureParser;
        this.planner = planner;
        this.promptAssembly = promptAssembly;
        this.promptBuilder = promptBuilder;
        this.resultParser = resultParser;
        this.validator = validator;
        this.publisher = publisher;
        this.invocation = invocation;
        this.capacity = capacity;
        this.guard = guard;
        this.properties = properties;
    }

    @Override
    public TaskOutcome execute(AgentReviewTask task) {
        List<AgentTaskTarget> targets = db.mapper(AgentTaskTargetMapper.class).selectList(
                new LambdaQueryWrapper<AgentTaskTarget>()
                        .eq(AgentTaskTarget::getTaskId, task.getId())
                        .orderByAsc(AgentTaskTarget::getOrdinal));
        if (targets.isEmpty()) {
            return TaskOutcome.failed("NO_TARGETS");
        }
        int threads = Math.max(1, Math.min(properties.getParallelTargets(), targets.size()));
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        List<Future<SpecialistTargetOutcome>> futures = new ArrayList<>();
        try {
            for (AgentTaskTarget target : targets) {
                futures.add(pool.submit(() -> executeTarget(task, target)));
            }
            List<SpecialistTargetOutcome> outcomes = new ArrayList<>();
            for (int i = 0; i < futures.size(); i++) {
                try {
                    outcomes.add(futures.get(i).get());
                } catch (ExecutionException failure) {
                    Throwable cause = failure.getCause();
                    if (cause instanceof ApiException api
                            && (api.errorCode() == ErrorCode.TASK_CANCELLED
                            || api.errorCode() == ErrorCode.TASK_DEADLINE)) {
                        futures.forEach(future -> future.cancel(true));
                        throw api;
                    }
                    log.error("目标 {} 执行异常", targets.get(i).getId(), cause);
                    finishTarget(targets.get(i).getId(), TaskStates.FAILED, "EXECUTION_ERROR");
                    outcomes.add(new SpecialistTargetOutcome(targets.get(i).getId(),
                            TaskStates.FAILED, "EXECUTION_ERROR"));
                } catch (InterruptedException interrupted) {
                    Thread.currentThread().interrupt();
                    throw new ApiException(ErrorCode.TASK_CANCELLED, "任务执行被中断");
                }
            }
            long succeeded = outcomes.stream()
                    .filter(outcome -> TaskStates.SUCCEEDED.equals(outcome.state())).count();
            long usable = outcomes.stream()
                    .filter(outcome -> TaskStates.SUCCEEDED.equals(outcome.state())
                            || TaskStates.PARTIAL.equals(outcome.state())).count();
            if (succeeded == outcomes.size()) {
                return TaskOutcome.succeeded();
            }
            if (usable > 0) {
                return TaskOutcome.partial("SOME_TARGETS_FAILED");
            }
            return TaskOutcome.failed("ALL_TARGETS_FAILED");
        } finally {
            pool.shutdownNow();
        }
    }

    private SpecialistTargetOutcome executeTarget(AgentReviewTask task, AgentTaskTarget target) {
        try {
            guard.requireActive(task.getId());
            updateTarget(target.getId(), TaskStates.PREPARING, null);
            PreparedTarget prepared = preparation.prepare(command(task, target));
            if (prepared.failed()) {
                finishTarget(target.getId(), TaskStates.FAILED, prepared.errorCode());
                return new SpecialistTargetOutcome(target.getId(), TaskStates.FAILED,
                        prepared.errorCode());
            }
            PreparedTarget enhanced = enhancement.enhance(prepared);
            ModelSnapshot model = model(task);
            Strategy strategy = strategy(task);
            CouplingFacts facts = facts(task, enhanced);
            boolean smartSplit = read(task.getInputSnapshot()).path("smartSplit").asBoolean(false);
            ModelSnapshot planningModel = model;
            for (int generation = 1; generation <= 3; generation++) {
                List<SpecialistUnitPlan> units = planner.plan(enhanced, facts, strategy.name(),
                        strategy.prompt(), planningModel, smartSplit);
                updateTarget(target.getId(), TaskStates.RUNNING, null);
                List<SpecialistUnitExecution> executions = new ArrayList<>();
                boolean unitFailed = false;
                String lastUnitError = null;
                boolean replan = false;
                for (SpecialistUnitPlan unit : units) {
                    guard.requireActive(task.getId());
                    AgentExecutionUnit row = createUnit(target.getId(), unit, generation);
                    try {
                        SpecialistUnitExecution execution = executeUnit(task, target, unit, row,
                                model, facts, strategy, !smartSplit);
                        guard.requireActive(task.getId());
                        updateUnit(row.getId(), TaskStates.SUCCEEDED);
                        executions.add(execution);
                    } catch (ApiException failure) {
                        updateUnit(row.getId(), TaskStates.FAILED);
                        if (failure.errorCode() == ErrorCode.TASK_CANCELLED
                                || failure.errorCode() == ErrorCode.TASK_DEADLINE) {
                            throw failure;
                        }
                        if (failure.errorCode() == ErrorCode.CONTEXT_LIMIT && smartSplit) {
                            if (generation == 3) {
                                throw failure;
                            }
                            var estimate = capacity.estimate(promptAssembly.assemble(
                                    promptBuilder.build(unit.target(), facts, strategy.name(),
                                            strategy.prompt())), planningModel);
                            int window = Math.max(1, Math.min(planningModel.contextWindow() - 1,
                                    (int) (estimate.required() * 0.75)));
                            planningModel = new ModelSnapshot(model.id(), model.name(), model.baseUrl(),
                                    model.modelName(), model.credential(), window, model.maxOutput(),
                                    model.tokenizer(), model.protocol(), model.revision());
                            replan = true;
                            break;
                        }
                        unitFailed = true;
                        lastUnitError = failure.errorCode().code();
                    }
                }
                if (replan) {
                    // 旧代仅保留诊断，不能带入新代结果。
                    continue;
                }
                if (executions.isEmpty()) {
                    finishTarget(target.getId(), TaskStates.FAILED, lastUnitError);
                    return new SpecialistTargetOutcome(target.getId(), TaskStates.FAILED, lastUnitError);
                }
                boolean complete = !unitFailed;
                String state = complete ? TaskStates.SUCCEEDED : TaskStates.PARTIAL;
                db.inTransaction(() -> {
                    guard.requireActiveLocked(task.getId());
                    publisher.publish(task, target, enhanced, executions, complete);

                publisher.publish(task, target, enhanced, executions, complete);
                if (finishTarget(target.getId(), state, complete ? null : "PARTIAL_UNITS") == 0) {
                    throw new ApiException(ErrorCode.TASK_CANCELLED, "目标已结束，拒绝迟到发布");
                }
                return null;
            });
            return new SpecialistTargetOutcome(target.getId(), state, null);
        }
        throw new ApiException(ErrorCode.CONTEXT_LIMIT, "容量重规划次数已用尽");
    } catch (ApiException failure) {
        if (failure.errorCode() == ErrorCode.TASK_CANCELLED
                || failure.errorCode() == ErrorCode.TASK_DEADLINE) {
            finishTarget(target.getId(), TaskStates.CANCELLED, failure.errorCode().code());
            throw failure;
        }
        finishTarget(target.getId(), TaskStates.FAILED, failure.errorCode().code());
        return new SpecialistTargetOutcome(target.getId(), TaskStates.FAILED,
                failure.errorCode().code());
    }
}

private SpecialistUnitExecution executeUnit(AgentReviewTask task, AgentTaskTarget target,
                                            SpecialistUnitPlan unit, AgentExecutionUnit row,
                                            ModelSnapshot model, CouplingFacts facts,
                                            Strategy strategy, boolean sendWhole) {
    PromptInput.FormatRetry retry = null;
    try {
        for (int attempt = 1; attempt <= SpecialistProtocolPolicy.maxAttempts(); attempt++) {
            guard.requireActive(task.getId());
            PromptInput input = promptBuilder.build(unit.target(), facts, strategy.name(),
                    strategy.prompt(), retry);
            AssembledPrompt prompt = promptAssembly.assemble(input);
            if (!sendWhole) {
                capacity.requireFits(prompt, model);
            }
            InvocationResult result = null;
            try {
                result = invocation.invoke(new InvocationRequest(model, prompt,
                        new InvocationScope(task.getId(), target.getId(), row.getId(),
                                task.getDeadlineAt()), sendWhole));
                guard.requireActive(task.getId());
                SpecialistResults.Result parsed = resultParser.parse(result.content(),
                        task.getSpecialistType());
                SpecialistResultValidator.ValidatedResult validated = validator.validate(parsed,
                        promptBuilder.context(unit.target(), facts));
                return new SpecialistUnitExecution(row.getId(), unit, validated, result.callId(), facts);
            } catch (ApiException failure) {
                if (result != null && failure.errorCode() == ErrorCode.MODEL_OUTPUT_INVALID) {
                    db.mapper(AgentModelCallMapper.class).update(null,
                            new LambdaUpdateWrapper<AgentModelCall>()
                                    .eq(AgentModelCall::getId, result.callId())
                                    .set(AgentModelCall::getState, "FAILED")
                                    .set(AgentModelCall::getErrorCode, failure.errorCode().code())
                                    .set(AgentModelCall::getErrorMessage, failure.getMessage()));
                }
                if (failure.errorCode() == ErrorCode.MODEL_OUTPUT_INVALID
                        && SpecialistProtocolPolicy.shouldRetry(attempt)) {
                    retry = SpecialistProtocolPolicy.diagnostic(attempt, failure,
                            result == null ? null : result.content());
                    continue;
                }
                throw failure;
            }
        }
        throw new ApiException(ErrorCode.MODEL_OUTPUT_INVALID, "格式重试次数已用尽");
    } finally {
        linkMaterials(row.getId(), unit.target());
    }
}

private PrepareCommand command(AgentReviewTask task, AgentTaskTarget target) {
    JsonNode input = read(task.getInputSnapshot());
    return new PrepareCommand(task.getProjectId(), task.getSpecialistType(),
            input.path("source").path("kind").asText("FILES"),
            input.path("source").path("branch").asText(null),
            target.getPath(), target.getOldPath(), target.getNote(),
            target.getHeadSha(), target.getBaseSha());
}

private CouplingFacts facts(AgentReviewTask task, PreparedTarget target) {
    if (!"COUPLING".equals(task.getSpecialistType())) {
        return null;
    }
    Material primary = target.targets().stream()
            .filter(material -> material.side() == Side.AFTER)
            .findFirst()
            .or(() -> target.targets().stream().filter(material -> material.side() == Side.FILE)
                    .findFirst())
            .orElse(target.targets().get(0));
    DeclarationResolver resolver = new DeclarationResolver(task.getProjectId(),
            primary.sha(), repository, structureParser);
    return couplingFacts.build(target, resolver);
}

private ModelSnapshot model(AgentReviewTask task) {
    JsonNode config = read(task.getConfigSnapshot()).path("model");
    String id = config.path("id").asText(null);
    if (id == null || id.isBlank()) {
        throw new ApiException(ErrorCode.CONFIG_INCOMPLETE, "任务缺少模型配置快照");
    }
    AgentModelConfig model = db.mapper(AgentModelConfigMapper.class).selectById(id);
    if (model == null) {
        throw new ApiException(ErrorCode.CONFIG_INCOMPLETE, "任务使用的模型配置已不存在");
    }
    return new ModelSnapshot(id, text(config, "name", model.getName()),
            text(config, "baseUrl", model.getBaseUrl()),
            text(config, "modelName", model.getModelName()), model.getCredential(),
            integer(config, "contextWindow", model.getContextWindow()),
            integer(config, "maxOutput", model.getMaxOutput()),
            text(config, "tokenizer", model.getTokenizer()),
            text(config, "protocol", model.getProtocol() == null ? "OPENAI_CHAT" : model.getProtocol()),
            integer(config, "revision", model.getRevision()));
}

private Strategy strategy(AgentReviewTask task) {
    JsonNode config = read(task.getConfigSnapshot());
    JsonNode strategy = config.path("strategy");
    JsonNode prompt = config.path("prompt");
    String name = strategy.path("name").asText(null);
    String content = prompt.path("content").asText(null);
    return new Strategy(name, content);
}

private AgentExecutionUnit createUnit(String targetId, SpecialistUnitPlan plan, int generation) {
    LocalDateTime now = AgentTime.now();
    AgentExecutionUnit row = new AgentExecutionUnit();
    row.setId(AgentIds.next());
    row.setTargetId(targetId);
    row.setGeneration(generation);
    row.setOrdinal(plan.ordinal());
    row.setRanges(json(ranges(plan)));
    row.setState(TaskStates.RUNNING);
    row.setRevision(0);
    row.setCreatedAt(now);
    row.setUpdatedAt(now);
    db.mapper(AgentExecutionUnitMapper.class).insert(row);
    return row;
}

private void linkMaterials(String unitId, PreparedTarget target) {
    List<AgentModelCall> calls = db.mapper(AgentModelCallMapper.class).selectList(

package com.codereview.agent.invocation;

import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;
import com.codereview.agent.api.ApiException;
import com.codereview.agent.api.ErrorCode;
import com.codereview.agent.db.AgentDatabase;
import com.codereview.agent.entity.AgentModelCall;
import com.codereview.agent.entity.AgentTaskQuota;
import com.codereview.agent.execution.TaskExecutionGuard;
import com.codereview.agent.mapper.AgentModelCallMapper;
import com.codereview.agent.mapper.AgentTaskQuotaMapper;
import com.codereview.agent.prompt.AssembledPrompt;
import com.codereview.agent.prompt.PromptAssemblyService;
import com.codereview.agent.prompt.PromptInput;
import com.codereview.agent.prompt.PromptPurpose;
import com.codereview.agent.support.AgentIds;
import com.codereview.agent.support.AgentTime;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;

import java.time.Duration;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Map;

/**
 * 公共模型调用入口。
 *
 * <p>顺序固定：容量判断 → 额度原子预留 → 请求正文落盘 → 发请求 → 记录结果。
 * 请求正文保存失败时绝不发请求；每次真实网络尝试各有一条 {@code model_call}，
 * 所有尝试都计入任务额度。暂态失败最多额外重试一次，鉴权、配置和协议错误不重试。
 *
 * <p>调用层只负责传输与分类；协议结构校验、格式重试和结果发布由专项执行层负责。
 */
@Service
@ConditionalOnProperty(prefix = "agent.datasource", name = "url")
public class ModelInvocationService {

    private final AgentDatabase db;
    private final ObjectMapper mapper;
    private final ModelTransport transport;
    private final ModelCapacityService capacity;
    private final PromptAssemblyService assembly;
    private final ModelInvocationProperties properties;
    private final ModelCallConcurrencyLimiter limiter;
    private final TaskExecutionGuard guard;

    public ModelInvocationService(AgentDatabase db, ObjectMapper mapper, ModelTransport transport,
                                  ModelCapacityService capacity, PromptAssemblyService assembly,
                                  ModelCallConcurrencyLimiter limiter,
                                  ModelInvocationProperties properties, TaskExecutionGuard guard) {
        this.db = db;
        this.mapper = mapper;
        this.transport = transport;
        this.capacity = capacity;
        this.assembly = assembly;
        this.limiter = limiter;
        this.properties = properties;
        this.guard = guard;
    }

    public InvocationResult invoke(InvocationRequest request) {
        ModelSnapshot model = request.model();
        AssembledPrompt prompt = request.prompt();
        InvocationScope scope = request.scope();
        requireModel(model);

        CapacityEstimate estimate = request.sendWholeSpecialist()
                ? capacity.estimate(prompt, model, request.outputReserve())
                : capacity.requireFits(prompt, model, request.outputReserve());
        String body = requestBody(model, prompt, estimate.outputReserve());
        int attempts = 1 + Math.max(0, properties.getTransportRetries());
        ApiException lastFailure = null;

        for (int attempt = 1; attempt <= attempts; attempt++) {
            boolean last = attempt == attempts;
            scope = activeScope(scope);
            timeoutFor(scope);
            ModelCallConcurrencyLimiter.Permit permit = limiter.acquire(scope.taskId(), scope.deadlineAt());
            try {
                scope = activeScope(scope);
                timeoutFor(scope);
                if (scope.taskId() != null) {
                    reserveQuota(scope.taskId());
                }
                AgentModelCall call = startCall(scope, request.reportId(), prompt, body, attempt, estimate);
                Duration timeout;
                try {
                    // 等待许可和请求落盘都可能跨过取消或期限；以真正发送前的状态为准。
                    scope = activeScope(scope);
                    timeout = timeoutFor(scope);
                } catch (ApiException stopped) {
                    finishFailure(call, stopped, null);
                    throw stopped;
                }
                try {
                    ModelTransport.TransportResponse response = transport.post(endpoint(model),
                            model.credential(), body, timeout);
                    if (response.status() >= 200 && response.status() < 300) {
                        return succeed(call, response, estimate, attempt);
                    }
                    ApiException failure = classify(response);
                    finishFailure(call, failure, response.body());
                    lastFailure = failure;
                    if (!failure.errorCode().retryable() || last) {
                        throw failure;
                    }
                } catch (ModelTransport.TransportFailure failure) {
                    ApiException mapped = new ApiException(
                            failure.timeout() ? ErrorCode.UPSTREAM_TIMEOUT : ErrorCode.MODEL_UNAVAILABLE,
                            failure.getMessage(), Map.of("attempt", attempt));
                    finishFailure(call, mapped, null);
                    lastFailure = mapped;
                    if (last) {
                        throw mapped;
                    }
                }
            } finally {
                permit.close();
            }
            scope = activeScope(scope);
            waitBeforeRetry(failureRetryAfter(lastFailure), scope);
        }
        throw lastFailure == null
                ? new ApiException(ErrorCode.INTERNAL_ERROR, "模型调用结束但没有结果")
                : lastFailure;
    }

    /**
     * 连通验证也走同一组装与调用入口：保存实际请求、计量并记录尝试，
     * 不再用另一套探针重建模板。结果本身是「通过／失败」，不抛 4xx。
     */
    public ValidationOutcome validate(ModelSnapshot model) {
        AssembledPrompt prompt = assembly.assemble(new PromptInput(PromptPurpose.VALIDATION, "1",
                null, null, null, "VALIDATION", null, null, null,
                List.of(), List.of(), List.of(), List.of(), null));
        try {
            InvocationResult result = invoke(new InvocationRequest(model, prompt,
                    InvocationScope.standalone(AgentTime.now().plusMinutes(1))));
            if (result.content() != null && !result.content().isBlank()) {
                return new ValidationOutcome(true, "连通成功，模型返回了正文", result.callId());
            }
            return new ValidationOutcome(false, "模型返回正文为空", result.callId());
        } catch (ApiException e) {
            return new ValidationOutcome(false, e.getMessage(), null);
        }
    }

    private AgentModelCall startCall(InvocationScope scope, String reportId, AssembledPrompt prompt,
                                     String body, int attempt, CapacityEstimate estimate) {
        LocalDateTime now = AgentTime.now();
        AgentModelCall call = new AgentModelCall();
        call.setId(AgentIds.next());
        call.setTaskId(scope.taskId());
        call.setReportId(reportId);
        call.setTargetId(scope.targetId());
        call.setUnitId(scope.unitId());
        call.setPurpose(prompt.purpose().wireName());
        call.setAttempt(attempt);
        call.setState("RUNNING");
        call.setRequestBody(body);
        call.setAdapterVersion(prompt.adapterVersion());
        call.setEstimateMethod(estimate.method());
        call.setCreatedAt(now);
        call.setStartedAt(now);
        db.mapper(AgentModelCallMapper.class).insert(call);
        return call;
    }

    private InvocationResult succeed(AgentModelCall call, ModelTransport.TransportResponse response,
                                     CapacityEstimate estimate, int attempt) {
        JsonNode root;
        try {
            root = mapper.readTree(response.body());
        } catch (JsonProcessingException e) {
            ApiException failure = new ApiException(ErrorCode.MODEL_OUTPUT_INVALID,
                    "模型返回的不是 JSON", Map.of("callId", call.getId()));
            finishFailure(call, failure, response.body());
            throw failure;
        }
        JsonNode choices = root.path("choices");
        if (!choices.isArray() || choices.isEmpty()) {
            ApiException failure = new ApiException(ErrorCode.MODEL_OUTPUT_INVALID,
                    "模型响应缺少 choices", Map.of("callId", call.getId()));
            finishFailure(call, failure, response.body());
            throw failure;
        }
        JsonNode first = choices.get(0);
        String finishReason = first.path("finish_reason").asText(null);
        if ("length".equals(finishReason)) {
            ApiException failure = new ApiException(ErrorCode.MODEL_OUTPUT_INVALID,
                    "模型输出因长度限制被截断", Map.of("callId", call.getId(),
                            "finishReason", finishReason));
            finishFailure(call, failure, response.body());

            finishFailure(call, failure, response.body());
            throw failure;
        }
        String content = textOf(first.path("message").path("content"));
        if (content == null || content.isBlank()) {
            ApiException failure = new ApiException(ErrorCode.MODEL_OUTPUT_INVALID,
                    "模型响应缺少正文", Map.of("callId", call.getId()));
            finishFailure(call, failure, response.body());
            throw failure;
        }
        JsonNode usage = root.path("usage").isObject() ? root.path("usage") : null;
        call.setState("SUCCEEDED");
        call.setResponseBody(response.body());
        call.setUsageJson(usage == null ? null : usage.toString());
        call.setFinishedAt(AgentTime.now());
        db.mapper(AgentModelCallMapper.class).updateById(call);
        return new InvocationResult(call.getId(), content, usage, finishReason, attempt,
                estimate.inputEstimate(), estimate.outputReserve(), estimate.method(),
                call.getAdapterVersion());
    }

    private void finishFailure(AgentModelCall call, ApiException failure, String responseBody) {
        call.setState("FAILED");
        call.setResponseBody(responseBody);
        call.setErrorCode(failure.errorCode().code());
        call.setErrorMessage(truncate(failure.getMessage(), 1000));
        call.setFinishedAt(AgentTime.now());
        db.mapper(AgentModelCallMapper.class).updateById(call);
    }

    private String requestBody(ModelSnapshot model, AssembledPrompt prompt, int outputReserve) {
        ObjectNode body = mapper.createObjectNode();
        body.put("model", model.modelName());
        body.put("temperature", 0);
        body.put("max_tokens", outputReserve);
        body.put("stream", false);
        if (prompt.jsonMode() && isDeepSeekModel(model)) {
            // DeepSeek defaults to thinking mode; its reasoning tokens share max_tokens with
            // the structured final answer and can consume the entire output budget.
            body.put("reasoning_effort", "none");
        }
        if (prompt.jsonMode()) {
            body.putObject("response_format").put("type", "json_object");
        }
        ArrayNode messages = body.putArray("messages");
        for (var message : prompt.messages()) {
            messages.addObject().put("role", message.role()).put("content", message.content());
        }
        try {
            return mapper.writeValueAsString(body);
        } catch (JsonProcessingException e) {
            throw new ApiException(ErrorCode.INTERNAL_ERROR, "请求正文序列化失败");
        }
    }

    private ApiException classify(ModelTransport.TransportResponse response) {
        int status = response.status();
        String body = response.body() == null ? "" : response.body();
        if (status == 401 || status == 403) {
            return new ApiException(ErrorCode.MODEL_UNAUTHORIZED, "模型凭据被拒绝",
                    Map.of("status", status));
        }
        if (status == 429) {
            Long retryAfter = retryAfterSeconds(response);
            return new ApiException(ErrorCode.RATE_LIMITED, "模型网关限流",
                    retryAfter == null ? Map.of("status", status)
                            : Map.of("status", status, "retryAfter", retryAfter));
        }
        if (status >= 500) {
            return new ApiException(ErrorCode.MODEL_UNAVAILABLE, "模型网关暂时不可用",
                    Map.of("status", status));
        }
        if (status == 400 && looksLikeContextLimit(body)) {
            return new ApiException(ErrorCode.CONTEXT_LIMIT, "模型报告上下文超限",
                    Map.of("status", status));
        }
        return new ApiException(ErrorCode.MODEL_BAD_REQUEST, "模型请求被拒绝",
                Map.of("status", status));
    }

    static boolean looksLikeContextLimit(String body) {
        try {
            JsonNode error = new ObjectMapper().readTree(body).path("error");
            return List.of("context_length_exceeded", "context_window_exceeded")
                    .contains(error.path("code").asText());
        } catch (Exception invalid) {
            return false;
        }
    }

    private InvocationScope activeScope(InvocationScope scope) {
        if (scope.taskId() == null) {
            return scope;
        }
        var task = guard.requireActive(scope.taskId());
        LocalDateTime deadline = scope.deadlineAt();
        if (task.getDeadlineAt() != null && (deadline == null || task.getDeadlineAt().isBefore(deadline))) {
            deadline = task.getDeadlineAt();
        }
        return new InvocationScope(scope.taskId(), scope.targetId(), scope.unitId(), deadline);
    }

    private Duration timeoutFor(InvocationScope scope) {
        Duration limit = Duration.ofSeconds(properties.getMaxReadTimeoutSeconds());
        if (scope.deadlineAt() == null) {
            return limit;
        }
        Duration remaining = Duration.between(AgentTime.now(), scope.deadlineAt());
        if (remaining.isNegative() || remaining.isZero()) {
            throw new ApiException(ErrorCode.TASK_DEADLINE, "任务已到达期限，未发送模型请求");
        }
        Duration capped = remaining.minusSeconds(1);
        if (capped.isNegative() || capped.isZero()) {
            throw new ApiException(ErrorCode.TASK_DEADLINE, "任务剩余期限不足一次调用");
        }
        return capped.compareTo(limit) < 0 ? capped : limit;
    }

    private void waitBeforeRetry(Long retryAfterSeconds, InvocationScope scope) {
        long wait = retryAfterSeconds != null
                ? Math.min(retryAfterSeconds * 1000, 3000)
                : properties.getRetryBaseMillis();
        if (wait <= 0) {
            wait = 1;
        }
        if (scope.deadlineAt() != null) {
            long remaining = Duration.between(AgentTime.now(), scope.deadlineAt()).toMillis();
            if (remaining <= wait + 500) {
                throw new ApiException(ErrorCode.TASK_DEADLINE, "任务剩余期限不足以重试");
            }
        }
        try {
            Thread.sleep(wait);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new ApiException(ErrorCode.MODEL_UNAVAILABLE, "模型重试被中断");
        }
    }

    private static Long failureRetryAfter(ApiException failure) {
        if (failure != null && failure.details() instanceof Map<?, ?> details
                && details.get("retryAfter") instanceof Number number) {
            return number.longValue();
        }
        return null;
    }

    private static Long retryAfterSeconds(ModelTransport.TransportResponse response) {
        String value = response.headers() == null ? null : response.headers().get("retry-after");
        if (value == null || value.isBlank()) {
            return null;
        }
        try {
            return Long.parseLong(value.trim());
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private void reserveQuota(String taskId) {
        AgentTaskQuotaMapper quotaMapper = db.mapper(AgentTaskQuotaMapper.class);
        int updated = quotaMapper.update(null, new LambdaUpdateWrapper<AgentTaskQuota>()
                .eq(AgentTaskQuota::getTaskId, taskId)
                .apply("reserved < hard_limit")
                .setSql("reserved = reserved + 1")
                .set(AgentTaskQuota::getUpdatedAt, AgentTime.now()));
        if (updated > 0) {
            return;
        }
        if (quotaMapper.selectById(taskId) == null) {
            LocalDateTime now = AgentTime.now();
            AgentTaskQuota quota = new AgentTaskQuota();
            quota.setTaskId(taskId);
            quota.setHardLimit(properties.getTaskCallLimit());
            quota.setReserved(1);
            quota.setCreatedAt(now);
            quota.setUpdatedAt(now);
            try {
                quotaMapper.insert(quota);
                return;
            } catch (DuplicateKeyException race) {
                if (quotaMapper.update(null, new LambdaUpdateWrapper<AgentTaskQuota>()
                        .eq(AgentTaskQuota::getTaskId, taskId)
                        .apply("reserved < hard_limit")
                        .setSql("reserved = reserved + 1")
                        .set(AgentTaskQuota::getUpdatedAt, now)) > 0) {
                    return;
                }
            }
        }
        throw new ApiException(ErrorCode.QUOTA_EXCEEDED,
                "任务请求额度已用尽（上限 " + properties.getTaskCallLimit() + " 次）",
                Map.of("taskId", taskId));
    }

